#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    // Number of chunks/threads to use
    int p = 1;
    #pragma omp parallel
    {
        #pragma omp single
        {
            p = omp_get_num_threads();
        }
    }

    if (p > n) p = n;
    if (p <= 1) {
        int running = 0;
        for (int i = 0; i < n; ++i) {
            running += x[n - 1 - i];
            output[i] = running;
        }
        return;
    }

    std::vector<int> chunkStart(p), chunkEnd(p), chunkSums(p, 0), chunkOffsets(p, 0);

    // Partition work into contiguous chunks in output index space [0..n-1]
    for (int t = 0; t < p; ++t) {
        chunkStart[t] = (t * n) / p;
        chunkEnd[t]   = ((t + 1) * n) / p;
    }

    #pragma omp parallel num_threads(p)
    {
        const int tid = omp_get_thread_num();
        const int s = chunkStart[tid];
        const int e = chunkEnd[tid];

        int local = 0;
        for (int i = s; i < e; ++i) {
            local += x[n - 1 - i];
            output[i] = local;
        }
        chunkSums[tid] = local;

        #pragma omp barrier

        // Single thread computes offsets for each chunk
        #pragma omp single
        {
            int acc = 0;
            for (int t = 0; t < p; ++t) {
                chunkOffsets[t] = acc;
                acc += chunkSums[t];
            }
        }

        const int add = chunkOffsets[tid];
        for (int i = s; i < e; ++i) {
            output[i] += add;
        }
    }
}
